#!/bin/bash
# ================================================
# SteuerApp – Selbst-entpackendes Installations-Skript
# Einfach ausführen: bash INSTALL_STEUERAPP.sh
# ================================================

ZIEL="$HOME/Downloads/SteuerApp.zip"
ORDNER="$HOME/Downloads/SteuerApp"

echo ""
echo "╔══════════════════════════════════════════╗"
echo "║    SteuerApp – Entpacken & Installieren  ║"
echo "╚══════════════════════════════════════════╝"
echo ""
echo "Entpacke SteuerApp nach: $HOME/Downloads/"

# ZIP dekodieren
echo "" | base64 --decode > "$ZIEL"

# Entpacken
mkdir -p "$ORDNER"
unzip -q -o "$ZIEL" -d "$HOME/Downloads/"

echo ""
echo "✅ Fertig! App liegt in:"
echo "   $ORDNER"
echo ""
echo "Nächste Schritte:"
echo "  1. Terminal öffnen"
echo "  2. cd ~/Downloads/SteuerApp"
echo "  3. chmod +x install_mac.sh && ./install_mac.sh"
echo ""

# Finder öffnen
open "$HOME/Downloads/SteuerApp" 2>/dev/null || true
